export function getSubpageContent(serviceSlug: string, capabilitySlug: string): SubpageContent | undefined {
  // Compound key lookup first (prevents collisions between services)
  const compoundKey = `${serviceSlug}/${capabilitySlug}`;
  if (subpageContentRegistry[compoundKey]) {
    return subpageContentRegistry[compoundKey];
  }
  // Direct key lookup
  if (subpageContentRegistry[capabilitySlug]) {
    return subpageContentRegistry[capabilitySlug];
  }
  return undefined;
}